insert into inv_transfer_receipt_discrepancy_adjudication_basis ( token_hash, discrepancy_case_id, case_version, fact_fingerprint, source_confirmation_event_id, target_confirmation_event_id, selected_shop_dept_id, scope_digest, required_permission, adjudicator_user_id, adjudicator_name, basis_status, issued_at, expires_at, create_by, create_time ) select #{basis.tokenHash}, c.discrepancy_case_id, c.case_version, c.fact_fingerprint, source_event.confirmation_event_id, target_event.confirmation_event_id, #{basis.selectedShopDeptId}, #{basis.scopeDigest}, #{basis.requiredPermission}, #{basis.adjudicatorUserId}, #{basis.adjudicatorName}, 'issued', #{basis.issuedAt}, #{basis.expiresAt}, #{basis.adjudicatorName}, #{basis.issuedAt} from inv_transfer_receipt_discrepancy_case c inner join inv_transfer_order o on o.transfer_id = c.transfer_id inner join inv_transfer_receipt_discrepancy_confirmation_event source_event on source_event.confirmation_event_id = #{basis.sourceConfirmationEventId} and source_event.discrepancy_case_id = c.discrepancy_case_id and source_event.party_role = 'source' and source_event.party_dept_id = coalesce( nullif(o.from_warehouse_id, 0), o.from_dept_id) inner join inv_transfer_receipt_discrepancy_confirmation_event target_event on target_event.confirmation_event_id = #{basis.targetConfirmationEventId} and target_event.discrepancy_case_id = c.discrepancy_case_id and target_event.party_role = 'target' and target_event.party_dept_id = coalesce( nullif(o.to_warehouse_id, 0), o.to_dept_id) where c.discrepancy_case_id = #{basis.caseId} and c.case_version = #{basis.caseVersion} and c.fact_fingerprint = #{basis.factFingerprint} and c.status = 'awaiting_confirmation' and source_event.case_version = c.case_version and target_event.case_version = c.case_version and source_event.fact_fingerprint = c.fact_fingerprint and target_event.fact_fingerprint = c.fact_fingerprint and source_event.decision = 'confirmed' and target_event.decision = 'confirmed' and source_event.operator_user_id <> #{basis.adjudicatorUserId} and target_event.operator_user_id <> #{basis.adjudicatorUserId} and source_event.confirmation_event_id = ( select max(source_latest.confirmation_event_id) from inv_transfer_receipt_discrepancy_confirmation_event source_latest where source_latest.discrepancy_case_id = c.discrepancy_case_id and source_latest.party_role = 'source' ) and target_event.confirmation_event_id = ( select max(target_latest.confirmation_event_id) from inv_transfer_receipt_discrepancy_confirmation_event target_latest where target_latest.discrepancy_case_id = c.discrepancy_case_id and target_latest.party_role = 'target' ) and #{basis.requiredPermission} = 'inv:transfer:discrepancy:adjudicate' and #{basis.basisStatus} = 'issued' and #{basis.adjudicatorUserId} > 0 and length(#{basis.adjudicatorName}) between 1 and 64 and #{basis.selectedShopDeptId} in
#{scopeDeptId}
and ( coalesce(nullif(o.from_warehouse_id, 0), o.from_dept_id) in
#{scopeDeptId}
or coalesce(nullif(o.to_warehouse_id, 0), o.to_dept_id) in
#{scopeDeptId}
) and #{basis.tokenHash} regexp '^[a-f0-9]{64}$' and #{basis.scopeDigest} regexp '^[a-f0-9]{64}$' and #{basis.expiresAt} = date_add( #{basis.issuedAt}, interval 5 minute) and not exists ( select 1 from inv_transfer_receipt_discrepancy_adjudication_basis prior where prior.token_hash = #{basis.tokenHash} )

