update inv_transfer_receipt_discrepancy_adjudication_basis basis
set basis_status = 'consumed',
    consumed_at = #{consumption.consumedAt},
    consumed_request_id = #{consumption.requestId},
    consumed_adjudication_id =
        #{consumption.adjudicationId},
    update_by = #{consumption.adjudicatorName},
    update_time = #{consumption.consumedAt}
where basis.adjudication_basis_id = #{consumption.basisId}
  and basis.token_hash = #{consumption.tokenHash}
  and basis.discrepancy_case_id = #{consumption.caseId}
  and basis.case_version = #{consumption.caseVersion}
  and basis.fact_fingerprint = #{consumption.factFingerprint}
  and basis.source_confirmation_event_id =
      #{consumption.sourceConfirmationEventId}
  and basis.target_confirmation_event_id =
      #{consumption.targetConfirmationEventId}
  and basis.selected_shop_dept_id =
      #{consumption.selectedShopDeptId}
  and basis.scope_digest = #{consumption.scopeDigest}
  and basis.required_permission =
      #{consumption.requiredPermission}
  and basis.adjudicator_user_id =
      #{consumption.adjudicatorUserId}
  and basis.adjudicator_name = #{consumption.adjudicatorName}
  and basis.issued_at = #{consumption.issuedAt}
  and basis.expires_at = #{consumption.expiresAt}
  and basis.basis_status = 'issued'
  and basis.consumed_at is null
  and basis.consumed_request_id is null
  and basis.consumed_adjudication_id is null
  and #{consumption.tokenHash} regexp '^[a-f0-9]{64}$'
  and #{consumption.factFingerprint} regexp '^[a-f0-9]{64}$'
  and #{consumption.scopeDigest} regexp '^[a-f0-9]{64}$'
  and #{consumption.requiredPermission} =
      'inv:transfer:discrepancy:adjudicate'
  and #{consumption.consumedAt} >= #{consumption.issuedAt}
  and #{consumption.consumedAt} < #{consumption.expiresAt}
  and exists (
      select 1
      from inv_transfer_receipt_discrepancy_adjudication adjudication
      where adjudication.adjudication_id =
            #{consumption.adjudicationId}
        and adjudication.request_id = #{consumption.requestId}
        and adjudication.discrepancy_case_id =
            #{consumption.caseId}
        and adjudication.case_version_before =
            #{consumption.caseVersion}
        and adjudication.case_version_after =
            #{consumption.caseVersion} + 1
        and adjudication.fact_fingerprint =
            #{consumption.factFingerprint}
        and adjudication.source_confirmation_event_id =
            #{consumption.sourceConfirmationEventId}
        and adjudication.target_confirmation_event_id =
            #{consumption.targetConfirmationEventId}
        and adjudication.adjudicator_user_id =
            #{consumption.adjudicatorUserId}
        and adjudication.adjudicator_name =
            #{consumption.adjudicatorName}
        and adjudication.required_permission =
            #{consumption.requiredPermission}
        and adjudication.plan_status = 'adjudication_planned'
  )
